use std::process::{Command, Output};
use std::io;

/// Executes an arbitrary shell command and returns its output.
///
/// # Arguments
/// * `cmd` - The shell command string to execute.
///
/// # Returns
/// * `Ok(String)` - Combined stdout/stderr output on success.
/// * `Err(io::Error)` - If the command could not be spawned.
pub fn run_command(cmd: &str) -> Result<String, io::Error> {
    let output: Output = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .output()?;

    let mut result = String::new();

    if !output.stdout.is_empty() {
        result.push_str(&String::from_utf8_lossy(&output.stdout));
    }
    if !output.stderr.is_empty() {
        result.push_str(&String::from_utf8_lossy(&output.stderr));
    }

    Ok(result)
}

/// Executes a command supplied as a pre-split argv list.
///
/// # Arguments
/// * `program` - The executable to run.
/// * `args`    - Slice of arguments to pass to the executable.
///
/// # Returns
/// * `Ok(String)` - Combined stdout/stderr output.
/// * `Err(io::Error)` - If the command could not be spawned.
pub fn run_command_argv(program: &str, args: &[&str]) -> Result<String, io::Error> {
    let output: Output = Command::new(program)
        .args(args)
        .output()?;

    let mut result = String::new();

    if !output.stdout.is_empty() {
        result.push_str(&String::from_utf8_lossy(&output.stdout));
    }
    if !output.stderr.is_empty() {
        result.push_str(&String::from_utf8_lossy(&output.stderr));
    }

    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_run_command_echo() {
        let out = run_command("echo hello").unwrap();
        assert_eq!(out.trim(), "hello");
    }
